rollback.sql:
BEGIN
    EXECUTE IMMEDIATE 'DROP USER ${app.user}';
EXCEPTION
    WHEN OTHERS THEN
        IF SQLCODE <> -1918 THEN
            RAISE;
        END IF;
END;

DECLARE
    v_existe NUMBER;

    PROCEDURE revocar(p_sentencia VARCHAR2) IS
    BEGIN
        EXECUTE IMMEDIATE p_sentencia;
    EXCEPTION
        WHEN OTHERS THEN
            -- ORA-01927: el privilegio no estaba concedido. ORA-00942: el objeto ya no existe
            -- porque el rollback del changelog ddl se adelanto. Ninguno de los dos es un fallo
            -- de reversibilidad: el estado final buscado es exactamente el que ya hay.
            IF SQLCODE NOT IN (-1927, -942) THEN
                RAISE;
            END IF;
    END revocar;
BEGIN
    SELECT COUNT(*) INTO v_existe FROM all_users WHERE username = UPPER('${app.user}');
    IF v_existe = 0 THEN
        RETURN;
    END IF;

    revocar('REVOKE SELECT, INSERT, UPDATE ON configuracion_smtp FROM ${app.user}');
    revocar('REVOKE SELECT, INSERT, UPDATE ON aviso_correo FROM ${app.user}');
    revocar('REVOKE SELECT, INSERT, UPDATE ON incidencia_adjunto FROM ${app.user}');
    revocar('REVOKE SELECT, INSERT, UPDATE ON incidencia FROM ${app.user}');
    revocar('REVOKE SELECT, INSERT, UPDATE ON sesion_usuario FROM ${app.user}');
    revocar('REVOKE SELECT, INSERT, UPDATE ON usuario FROM ${app.user}');
END;

