    revocar('REVOKE SELECT ON cat_estado_incidencia FROM ${app.user}');
    revocar('REVOKE SELECT ON cat_categoria_incidencia FROM ${app.user}');
    revocar('REVOKE SELECT ON cat_sala FROM ${app.user}');
    revocar('REVOKE SELECT ON cat_oficina FROM ${app.user}');
    revocar('REVOKE SELECT ON permiso_rol_operacion FROM ${app.user}');
    revocar('REVOKE SELECT ON cat_operacion FROM ${app.user}');
    revocar('REVOKE SELECT ON cat_rol FROM ${app.user}');
END;

changeSet.sql:
DECLARE
    v_n    NUMBER;
    c_app  CONSTANT VARCHAR2(128 CHAR) := UPPER('${app.user}');

    PROCEDURE exigir_privilegios(p_objeto VARCHAR2, p_esperados VARCHAR2, p_codigo NUMBER) IS
        l_lista VARCHAR2(400 CHAR);
    BEGIN
        SELECT LISTAGG(privilege, ',') WITHIN GROUP (ORDER BY privilege)
          INTO l_lista
          FROM (SELECT DISTINCT privilege
                  FROM user_tab_privs
                 WHERE grantee    = c_app
                   AND owner      = USER
                   AND table_name = UPPER(p_objeto));
        IF NVL(l_lista, '(ninguno)') <> p_esperados THEN
            RAISE_APPLICATION_ERROR(p_codigo, 'ORACULO REQ-047: el usuario de aplicacion tiene sobre ' || p_objeto ||
                ' los privilegios [' || NVL(l_lista, '(ninguno)') || '] y deberia tener exactamente [' || p_esperados || ']');
        END IF;
    END exigir_privilegios;
BEGIN
    -- (1) REQ-047: NINGUN objeto del esquema concede DELETE al usuario de aplicacion.
    SELECT COUNT(*) INTO v_n
      FROM user_tab_privs
     WHERE grantee   = c_app
       AND owner     = USER
       AND privilege = 'DELETE';
    IF v_n <> 0 THEN
        RAISE_APPLICATION_ERROR(-20750, 'ORACULO REQ-047: el usuario de aplicacion tiene el privilegio DELETE sobre ' ||
            v_n || ' objetos del esquema y no debe tenerlo sobre ninguno: las bajas son siempre logicas');
    END IF;

    -- (2) Tablas transaccionales: SELECT, INSERT y UPDATE, nada mas.
    exigir_privilegios('usuario',             'INSERT,SELECT,UPDATE', -20751);
    exigir_privilegios('sesion_usuario',      'INSERT,SELECT,UPDATE', -20751);
    exigir_privilegios('incidencia',          'INSERT,SELECT,UPDATE', -20751);
    exigir_privilegios('incidencia_adjunto',  'INSERT,SELECT,UPDATE', -20751);
    exigir_privilegios('aviso_correo',        'INSERT,SELECT,UPDATE', -20751);
    exigir_privilegios('configuracion_smtp',  'INSERT,SELECT,UPDATE', -20751);

    -- (3) Tablas de historico: SELECT e INSERT, nada mas. Ni UPDATE ni DELETE: son append-only.
    exigir_privilegios('usuario_historico',            'INSERT,SELECT', -20752);
    exigir_privilegios('usuario_password_historico',   'INSERT,SELECT', -20752);
    exigir_privilegios('auditoria_acceso',             'INSERT,SELECT', -20752);
    exigir_privilegios('incidencia_historico',         'INSERT,SELECT', -20752);
    exigir_privilegios('aviso_correo_intento',         'INSERT,SELECT', -20752);
    exigir_privilegios('resolucion_destinatario_log',  'INSERT,SELECT', -20752);

    -- (4) Informes de verificacion de integridad (REQ-152).
    exigir_privilegios('integridad_informe',  'INSERT,SELECT,UPDATE', -20753);
    exigir_privilegios('integridad_hallazgo', 'INSERT,SELECT',        -20753);

    -- (5) Catalogos: solo lectura.
    exigir_privilegios('cat_rol',                  'SELECT', -20754);
    exigir_privilegios('cat_operacion',            'SELECT', -20754);
    exigir_privilegios('permiso_rol_operacion',    'SELECT', -20754);
    exigir_privilegios('cat_oficina',              'SELECT', -20754);
    exigir_privilegios('cat_sala',                 'SELECT', -20754);
    exigir_privilegios('cat_categoria_incidencia', 'SELECT', -20754);
    exigir_privilegios('cat_estado_incidencia',    'SELECT', -20754);
    exigir_privilegios('cat_transicion_incidencia','SELECT', -20754);
    exigir_privilegios('cat_motivo_desactivacion', 'SELECT', -20754);

    -- (6) Vistas de consulta y de invariante: solo lectura.
    exigir_privilegios('v_filtro_sala',             'SELECT', -20755);
    exigir_privilegios('v_filtro_oficina',          'SELECT', -20755);
    exigir_privilegios('v_filtro_categoria',        'SELECT', -20755);
    exigir_privilegios('v_recuento_incidencias',    'SELECT', -20755);
    exigir_privilegios('v_chk_incidencia_sin_alta', 'SELECT', -20755);
    exigir_privilegios('v_chk_estado_desalineado',  'SELECT', -20755);
    exigir_privilegios('v_chk_cadena_hash',         'SELECT', -20755);
    exigir_privilegios('v_chk_cierre_1a1',          'SELECT', -20755);

    -- (7) Segunda barrera: los siete triggers de inmutabilidad existen y estan activos, de modo
    --     que el DELETE tampoco prospera desde la cuenta duena del esquema.
    SELECT COUNT(*) INTO v_n
      FROM user_triggers
     WHERE trigger_name IN ('TRG_USUARIO_HISTORICO_INMUTABLE',
                            'TRG_AUDITORIA_ACCESO_INMUTABLE',
                            'TRG_INCIDENCIA_HISTORICO_INMUTABLE',
                            'TRG_AVISO_CORREO_INTENTO_INMUTABLE',
                            'TRG_RESOLUCION_DEST_INMUTABLE',
                            'TRG_INTEGRIDAD_HALLAZGO_APPEND',
                            'TRG_INTEGRIDAD_INFORME_APPEND')
       AND status = 'ENABLED'
       AND triggering_event LIKE '%DELETE%';
    IF v_n <> 7 THEN
        RAISE_APPLICATION_ERROR(-20756, 'ORACULO REQ-015 / REQ-065: se esperaban 7 triggers de inmutabilidad activos que rechacen el DELETE y hay ' || v_n);
    END IF;
END;
